/// Child-friendly interactive stories. Each tale has three narrated scenes and
/// one two-option interaction in the middle. Choices are both safe; neither
/// removes stars, scores or imposes penalties.
class EnchantedStory {
  const EnchantedStory(this.title, this.friend, this.opening, this.challenge,
    this.question, this.optionA, this.optionB, this.answerA, this.answerB,
    this.ending, this.heart);
  final String title, friend, opening, challenge, question;
  final String optionA, optionB, answerA, answerB, ending, heart;
}

